#define STB_IMAGE_IMPLEMENTATION
#include "repo-vul/src-vul/stb/stb_image.h"
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    int x, y, n;
    unsigned char *img = stbi_load(argv[1], &x, &y, &n, 4);
    if (img) {
        printf("loaded %dx%d n=%d\n", x, y, n);
        free(img);
    } else {
        printf("failed: %s\n", stbi_failure_reason());
    }
    return 0;
}
EOF
gcc -g -fsanitize=address -o test_harness test_harness.c 2>&1 | head -20 && echo "BUILD OK" && ./test_harness /workspace/poc.jpg 2>&1 | head -40

